php artisan make:seeder RoleSeeder

# داخل database/seeders/DatabaseSeeder.php
public function run(): void
{
    $this->call([
        RoleSeeder::class,
        PostSeeder::class,
    ]);
}

# تشغيل كل البذور المسجَّلة
php artisan db:seed

# تشغيل بذرة واحدة فقط
php artisan db:seed --class=RoleSeeder

php artisan make:factory PostFactory

# داخل database/factories/PostFactory.php
public function definition(): array
{
    return [
        'title' => fake()->sentence(),
        'body' => fake()->paragraphs(3, true),
        'published' => fake()->boolean(),
    ];
}

# الاستخدام: 10 منشورات وهمية
Post::factory()->count(10)->create();

php artisan make:request StorePostRequest

# داخل app/Http/Requests/StorePostRequest.php
public function authorize(): bool
{
    return true;
}

public function rules(): array
{
    return [
        'title' => 'required|max:255',
        'body' => 'required',
    ];
}

# داخل المتحكّم — التحقّق يحصل تلقائيًا قبل تنفيذ هذا التابع
public function store(StorePostRequest $request)
{
    Post::create($request->validated());
}

php artisan make:policy PostPolicy --model=Post

# داخل app/Policies/PostPolicy.php
public function update(User $user, Post $post): bool
{
    return $user->id === $post->user_id;
}

# الاستخدام بالمتحكّم
public function update(Request $request, Post $post)
{
    $this->authorize('update', $post);
    // ...
}

php artisan tinker

