>>> App\Models\Post::create(['title' => 'تجربة', 'body' => '...']);
>>> exit

# داخل routes/console.php
use Illuminate\Support\Facades\Schedule;

Schedule::command('emails:send')->daily();
Schedule::call(fn () => Cache::flush())->weekly();

# إدخال cron واحد فقط على الخادم
* * * * * cd /path-to-project && php artisan schedule:run >> /dev/null 2>&1

# تشغيل محلي أثناء التطوير (بلا حاجة لـ cron)
php artisan schedule:work

# معاينة كل المهام المجدولة ووقت تنفيذها القادم
php artisan schedule:list
